def min_rolls_to_get_points(x):
    # The possible values Mishka can roll on the dice
    dice_values = [2, 3, 4, 5, 6, 7]

    # Initialize a list to store the minimum rolls needed for each sum up to x
    min_rolls = [float('inf')] * (x + 1)
    min_rolls[0] = 0  # Base case: 0 points need 0 rolls

    # Dynamic programming to find the minimum rolls for each sum
    for target in range(1, x + 1):
        for value in dice_values:
            if target >= value:
                min_rolls[target] = min(min_rolls[target], min_rolls[target - value] + 1)

    return min_rolls[x]

