def min_rolls_to_get_points(t, queries):
    results = []
    for x in queries:
        # Initialize the minimum rolls to a large number
        min_rolls = float('inf')

        # Check all possible combinations of dice faces
        for a in range(2, 8):
            for b in range(2, 8):
                if a == b:
                    continue
                for c in range(2, 8):
                    if c == a or c == b:
                        continue
                    for d in range(2, 8):
                        if d == a or d == b or d == c:
                            continue
                        for e in range(2, 8):
                            if e == a or e == b or e == c or e == d:
                                continue
                            for f in range(2, 8):
                                if f == a or f == b or f == c or f == d or f == e:
                                    continue

                                # Calculate the sum of the combination
                                total_sum = a + b + c + d + e + f

                                # Calculate the number of rolls needed
                                rolls = (x + total_sum - 1) // total_sum

                                # Update the minimum rolls if a better solution is found
                                min_rolls = min(min_rolls, rolls)

        # Append the result for the current query
        results.append(min_rolls)

    return results

