def min_rolls_to_get_points(x):
    # The minimum number of rolls needed is the smallest integer n such that
    # 6^n >= x. This is equivalent to finding the smallest n where
    # n * log(6) >= log(x), which simplifies to n >= log(x) / log(6).
    import math
    return math.ceil(math.log(x) / math.log(6))

